import { Table, FieldNameColumn, ReferenceColumn, StringColumn, GuidColumn, BooleanColumn } from '../../db'

export const dl_definition_rel_set = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'source_table_field',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Setter Field Definitions',
    name: 'dl_definition_rel_set',
    schema: {
        matcher_table_field: FieldNameColumn({
            dependent: 'matcher_table',
            label: [
                {
                    hint: 'Specifies the field in the matching table',
                    label: 'Matcher table field',
                    plural: 'Matcher table fields',
                },
            ],
            mandatory: true,
        }),
        source_table_field: FieldNameColumn({
            dependent: 'source_table',
            label: [
                {
                    hint: 'Specifies the field in the source table',
                    label: 'Source table field',
                    plural: 'Source table fields',
                },
            ],
            mandatory: true,
        }),
        dl_definition: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Data Lookup',
            referenceTable: 'dl_definition',
        }),
        matcher_table: StringColumn({
            default: 'javascript:parent.matcher_table',
            label: 'Matcher table',
            maxLength: 80,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        always_replace: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If true, a matching lookup will update the source field even if the matching field is blank',
                    label: 'Always replace',
                    plural: 'Always replaces',
                },
            ],
        }),
        source_table: StringColumn({
            default: 'javascript:parent.source_table',
            label: 'Source table',
            maxLength: 80,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
    },
})
